CREATE VIEW `v_product_revenue` AS
  SELECT
    p.`id` AS `productId`,
    p.`name` AS `productName`,
    COUNT(s.`id`) AS `sales`,
    CAST(SUM(s.`amountCents`) AS SIGNED) AS `revenueCents`,
    COALESCE(CAST(SUM(s.`amountCents`) AS SIGNED), 0) AS `revenueOrZero`
